/** Scoped-storage fixture owner. Only its recorded fixture URIs may be removed. */
public final class PhotoFixtures extends Instrumentation {
 private Bundle args;public void onCreate(Bundle b){super.onCreate(b);args=b;start();}
 public void onStart(){JSONArray records=new JSONArray();File manifest=new File(getTargetContext().getFilesDir(),"fixture-uris.json");try{
  if(args!=null&&args.getString("operation","import").equals("remove")){if(manifest.exists()){records=new JSONArray(Files.readString(manifest.toPath()));for(int i=0;i<records.length();i++)getTargetContext().getContentResolver().delete(Uri.parse(records.getJSONObject(i).getString("uri")),null,null);manifest.delete();}}
  else if(args!=null&&args.getString("operation","").equals("edit")){records=new JSONArray(Files.readString(manifest.toPath()));android.graphics.Bitmap face=android.graphics.BitmapFactory.decodeFile(new File(getTargetContext().getFilesDir(),"portrait.jpg").getPath());android.graphics.Bitmap pair=android.graphics.Bitmap.createBitmap(face.getWidth()*2,face.getHeight(),android.graphics.Bitmap.Config.ARGB_8888);android.graphics.Canvas canvas=new android.graphics.Canvas(pair);canvas.drawBitmap(face,0,0,null);canvas.drawBitmap(face,face.getWidth(),0,null);face.recycle();android.graphics.Matrix turn=new android.graphics.Matrix();turn.postRotate(270);android.graphics.Bitmap stored=android.graphics.Bitmap.createBitmap(pair,0,0,pair.getWidth(),pair.getHeight(),turn,true);pair.recycle();File file=new File(getTargetContext().getCacheDir(),"edited-fixture.jpg");try(OutputStream stream=new FileOutputStream(file)){stored.compress(android.graphics.Bitmap.CompressFormat.JPEG,95,stream);}stored.recycle();android.media.ExifInterface exif=new android.media.ExifInterface(file.getPath());exif.setAttribute(android.media.ExifInterface.TAG_MODEL,"AIOSFixtureCamera");exif.setAttribute(android.media.ExifInterface.TAG_MAKE,"AIOSFixture");exif.setAttribute(android.media.ExifInterface.TAG_DATETIME_ORIGINAL,"2026:10:25 12:00:00");exif.setAttribute("OffsetTimeOriginal","+08:00");exif.setAttribute(android.media.ExifInterface.TAG_ORIENTATION,"6");exif.setAttribute("GPSLatitude","22/1,18/1,0/1");exif.setAttribute("GPSLatitudeRef","N");exif.setAttribute("GPSLongitude","114/1,12/1,0/1");exif.setAttribute("GPSLongitudeRef","E");exif.saveAttributes();Uri uri=Uri.parse(records.getJSONObject(0).getString("uri"));try(InputStream in=new FileInputStream(file);OutputStream out=getTargetContext().getContentResolver().openOutputStream(uri,"wt")){in.transferTo(out);}ContentValues values=new ContentValues();values.put(MediaStore.Images.Media.DISPLAY_NAME,"AIOS_test_edited_portrait.jpg");getTargetContext().getContentResolver().update(uri,values,null,null);file.delete();}
  else{if(manifest.exists())throw new IllegalStateException("Fixtures already imported");File directory=new File(getTargetContext().getFilesDir(),"fixtures");File[] files=directory.listFiles((d,n)->n.endsWith(".jpg"));Arrays.sort(files);int count=Integer.parseInt(args.getString("count","172"));
   for(int n=0;n<count;n++){File file=files[n%files.length];ContentValues values=new ContentValues();values.put(MediaStore.Images.Media.DISPLAY_NAME,"AIOS_test_"+String.format(Locale.ROOT,"%04d",n)+"_"+file.getName());values.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/AIOSSearchAcceptance-20261025/");values.put(MediaStore.Images.Media.MIME_TYPE,"image/jpeg");values.put(MediaStore.Images.Media.IS_PENDING,1);Uri uri=getTargetContext().getContentResolver().insert(MediaStore.Images.Media.getContentUri(MediaStore.VOLUME_EXTERNAL_PRIMARY),values);records.put(new JSONObject().put("uri",uri.toString()).put("fixture",file.getName()));Files.writeString(manifest.toPath(),records.toString());try(InputStream in=new FileInputStream(file);OutputStream out=getTargetContext().getContentResolver().openOutputStream(uri)){in.transferTo(out);}ContentValues ready=new ContentValues();ready.put(MediaStore.Images.Media.IS_PENDING,0);getTargetContext().getContentResolver().update(uri,ready,null,null);}
  }
  Bundle result=new Bundle();result.putInt("fixtures",records.length());finish(-1,result);
 }catch(Exception e){Bundle result=new Bundle();result.putString("error",android.util.Log.getStackTraceString(e));finish(1,result);}}
}
